class Solution {
public:
    vector<vector<int>> pathSum(TreeNode* root, int targetSum) {
        vector<vector<int>> res;
        vector<int> path;
        dfs(root, targetSum, path, res);
        return res;
    }
private:
    void dfs(TreeNode* node, int remaining, vector<int>& path, vector<vector<int>>& res) {
        if (!node) return;
        path.push_back(node->val);
        if (!node->left && !node->right && remaining == node->val) {
            res.push_back(path);
        } else {
            dfs(node->left, remaining - node->val, path, res);
            dfs(node->right, remaining - node->val, path, res);
        }
        path.pop_back();
    }
};

class Solution {
    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        dfs(root, targetSum, path, res);
        return res;
    }
    private void dfs(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> res) {
        if (node == null) return;
        path.add(node.val);
        if (node.left == null && node.right == null && remaining == node.val) {
            res.add(new ArrayList<>(path));
        } else {
            dfs(node.left, remaining - node.val, path, res);
            dfs(node.right, remaining - node.val, path, res);
        }
        path.remove(path.size() - 1);
    }
}

var pathSum = function(root, targetSum) {
    const res = [];
    const path = [];
    function dfs(node, remaining) {
        if (!node) return;
        path.push(node.val);
        if (!node.left && !node.right && remaining === node.val) {
            res.push([...path]);
        } else {
            dfs(node.left, remaining - node.val);
            dfs(node.right, remaining - node.val);
        }
        path.pop();
    }
    dfs(root, targetSum);
    return res;
};
